/**
 * One turn of a conversation (`design/components/chat-message.md`).
 *
 * Generated by `pnpm shells` from `packages/shells/src/members/chat-message.ts`, the member's
 * framework-neutral description. Never edit it by hand: change the description and
 * run `pnpm shells`.
 */
import { Component, ViewEncapsulation, input } from '@angular/core'

import {
  Icon,
  MEMBER_PROVIDERS,
  SlotOutlet,
  SlotTemplate,
  useMember,
  type IconProps,
} from '@polymorph/angular'
import styles from '@polymorph/recipes/ai/chat-message.module.css'
import { Avatar, type AvatarProps } from '../structure/Avatar'

export type ChatMessageStatus = NonNullable<ChatMessageProps['status']>

export type ChatRole = NonNullable<ChatMessageProps['role']>

/** One turn of a conversation: the inputs it takes, by the React member's prop names. */
export interface ChatMessageProps {
  /**
   * The speaker's name, used as the article's accessible name and first in the meta row.
   */
  author: string
  /**
   * The speaker's picture, replaced by the reader's initials or the model's mark when absent.
   */
  avatar?: string
  /**
   * The speaker's role, which sets the layout and is the only frame choice the caller makes.
   */
  role: 'user' | 'system' | 'assistant'
  /**
   * The turn's status, where `complete` is the rest state and sets no attribute.
   */
  status?: 'error' | 'streaming' | 'complete' | 'stopped'
  /**
   * The app's text for `stopped` or `error`, such as "Stopped" or "Something went wrong".
   */
  statusMessage?: string
  /**
   * The time, preformatted by the app (Timeline's rule for time).
   */
  time?: string
}

/** One turn of a conversation. */
@Component({
  selector: 'pm-chat-message',
  encapsulation: ViewEncapsulation.None,
  host: { style: 'display: contents' },
  providers: [...MEMBER_PROVIDERS],
  imports: [SlotOutlet, SlotTemplate, Avatar, Icon],
  // prettier-ignore
  template: `<ng-template pmSlot="actions" [pmSlotOf]="$"><ng-content select="[slot=actions]" /></ng-template>
<ng-template pmSlot="default" [pmSlotOf]="$"><ng-content /></ng-template>
<article
[attr.class]="e1()"
[attr.data-role]="e2()"
[attr.data-status]="e3()"
[attr.aria-label]="e4()"
[attr.aria-busy]="e5()"
data-member="chat-message"
>@if (e6()) {<!-- mark -->
<span
[attr.class]="e7()"
>@if (e8()) {<!-- model -->
<span
[attr.class]="e9()"
aria-hidden="true"
><pm-icon
name="model"
size="sm"
></pm-icon></span>} @else {<pm-avatar
[name]="e10()"
[src]="e11()"
size="md"
></pm-avatar>}</span>}
<!-- body -->
<div
[attr.class]="e12()"
>@if (e6()) {<!-- meta -->
<div
[attr.class]="e13()"
><!-- author -->
<span
[attr.class]="e14()"
>{{ e15() }}</span>
@if (e16()) {<!-- time -->
<span
[attr.class]="e17()"
>{{ e18() }}</span>}</div>}
<!-- content -->
<div
[attr.class]="e19()"
><ng-container [pmSlotOutlet]="'default'" [pmSlotOf]="$" /></div>
@if (e20()) {<!-- notice -->
<p
[attr.class]="e21()"
><!-- noticeGlyph -->
<span
[attr.class]="e22()"
><pm-icon
[name]="e23()"
size="sm"
></pm-icon></span>{{ e24() }}</p>}
@if (e25()) {<!-- actions -->
<div
[attr.class]="e26()"
><ng-container [pmSlotOutlet]="'actions'" [pmSlotOf]="$" /></div>}</div></article>`,
})
export class ChatMessage {
  /**
   * The speaker's name, used as the article's accessible name and first in the meta row.
   */
  readonly author = input.required<ChatMessageProps['author']>()
  /**
   * The speaker's picture, replaced by the reader's initials or the model's mark when absent.
   */
  readonly avatar = input<ChatMessageProps['avatar']>(undefined)
  /**
   * The speaker's role, which sets the layout and is the only frame choice the caller makes.
   */
  readonly role = input.required<ChatMessageProps['role']>()
  /**
   * The turn's status, where `complete` is the rest state and sets no attribute.
   */
  readonly status = input<
    Exclude<ChatMessageProps['status'], undefined>,
    ChatMessageProps['status']
  >('complete', {
    transform: (value: ChatMessageProps['status']) => (value === undefined ? 'complete' : value),
  })
  /**
   * The app's text for `stopped` or `error`, such as "Stopped" or "Something went wrong".
   */
  readonly statusMessage = input<ChatMessageProps['statusMessage']>(undefined)
  /**
   * The time, preformatted by the app (Timeline's rule for time).
   */
  readonly time = input<ChatMessageProps['time']>(undefined)
  protected readonly $ = useMember({
    events: [],
    props: {
      author: () => this.author(),
      avatar: () => this.avatar(),
      role: () => this.role(),
      status: () => this.status(),
      statusMessage: () => this.statusMessage(),
      time: () => this.time(),
    },
  })
  protected readonly $p = this.$.props

  protected e1() {
    return styles.message
  }

  protected e2() {
    return this.$p.role
  }

  protected e3() {
    return this.$p.status === 'complete' ? undefined : this.$p.status
  }

  protected e4() {
    return this.$p.author
  }

  protected e5() {
    return this.$p.status === 'streaming' ? true : undefined
  }

  protected e6() {
    return this.$p.role !== 'system'
  }

  protected e7() {
    if (!(this.$p.role !== 'system')) return undefined as never
    return styles.mark
  }

  protected e8() {
    if (!(this.$p.role !== 'system')) return undefined as never
    return this.$p.role === 'assistant' && this.$p.avatar === undefined
  }

  protected e9() {
    if (!(this.$p.role !== 'system')) return undefined as never
    if (!(this.$p.role === 'assistant' && this.$p.avatar === undefined)) return undefined as never
    return styles.model
  }

  protected e10(): AvatarProps['name'] {
    if (!(this.$p.role !== 'system')) return undefined as never
    if (this.$p.role === 'assistant' && this.$p.avatar === undefined) return undefined as never
    return this.$p.author
  }

  protected e11(): AvatarProps['src'] {
    if (!(this.$p.role !== 'system')) return undefined as never
    if (this.$p.role === 'assistant' && this.$p.avatar === undefined) return undefined as never
    return this.$p.avatar
  }

  protected e12() {
    return styles.body
  }

  protected e13() {
    if (!(this.$p.role !== 'system')) return undefined as never
    return styles.meta
  }

  protected e14() {
    if (!(this.$p.role !== 'system')) return undefined as never
    return styles.author
  }

  protected e15() {
    if (!(this.$p.role !== 'system')) return undefined as never
    return this.$p.author
  }

  protected e16() {
    if (!(this.$p.role !== 'system')) return undefined as never
    return this.$p.time !== undefined
  }

  protected e17() {
    if (!(this.$p.role !== 'system')) return undefined as never
    if (!(this.$p.time !== undefined)) return undefined as never
    return styles.time
  }

  protected e18() {
    if (!(this.$p.role !== 'system')) return undefined as never
    if (!(this.$p.time !== undefined)) return undefined as never
    return this.$p.time
  }

  protected e19() {
    return styles.content
  }

  protected e20() {
    return (
      (this.$p.status === 'stopped' || this.$p.status === 'error') &&
      this.$p.statusMessage !== undefined
    )
  }

  protected e21() {
    if (!(
      (this.$p.status === 'stopped' || this.$p.status === 'error') &&
      this.$p.statusMessage !== undefined
    ))
      return undefined as never
    return styles.notice
  }

  protected e22() {
    if (!(
      (this.$p.status === 'stopped' || this.$p.status === 'error') &&
      this.$p.statusMessage !== undefined
    ))
      return undefined as never
    return styles.noticeGlyph
  }

  protected e23(): IconProps['name'] {
    if (!(
      (this.$p.status === 'stopped' || this.$p.status === 'error') &&
      this.$p.statusMessage !== undefined
    ))
      return undefined as never
    return this.$p.status === 'error' ? 'error' : 'warning'
  }

  protected e24() {
    if (!(
      (this.$p.status === 'stopped' || this.$p.status === 'error') &&
      this.$p.statusMessage !== undefined
    ))
      return undefined as never
    return this.$p.statusMessage
  }

  protected e25() {
    return this.$.filled('actions')
  }

  protected e26() {
    if (!this.$.filled('actions')) return undefined as never
    return styles.actions
  }
}
